const NOTIF_ICON_MAP = {
  application: "clipboard", broadcast: "megaphone", invitation: "party",
  profile: "eye", opportunity: "sparkles",
};

/* HTML string SVGs for template literals (e.g., Leaflet popups) */
const EIS = {
  mapPin: '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="display:inline-block;vertical-align:middle;margin-right:2px"><path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0"/><circle cx="12" cy="10" r="3"/></svg>',
};

/* ━━━ NETWORK MAP ━━━ */
function NetworkMap({ items, networkTab, darkMode }) {
  const mapRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const markersRef = useRef([]);

  useEffect(() => {
    if (!mapRef.current) return;

    // Initialize map if not already done
    if (!mapInstanceRef.current) {
      mapInstanceRef.current = L.map(mapRef.current, {
        center: [48, 10],
        zoom: 3,
        zoomControl: true,
        scrollWheelZoom: true,
        dragging: true,
        minZoom: 2,
        maxZoom: 18,
      });
      L.tileLayer(
        darkMode
          ? "https://{s}.basemaps.cartocdn.com/rastertiles/dark_all/{z}/{x}/{y}{r}.png"
          : "https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png",
        { attribution: '&copy; <a href="https://carto.com/">CARTO</a> &copy; <a href="https://www.openstreetmap.org/copyright">OSM</a>', subdomains: "abcd", maxZoom: 19 }
      ).addTo(mapInstanceRef.current);
    }

    return () => {
      // Cleanup on unmount
      if (mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
      }
    };
  }, []);

  // Update tile layer on dark mode change
  useEffect(() => {
    if (!mapInstanceRef.current) return;
    mapInstanceRef.current.eachLayer(layer => {
      if (layer instanceof L.TileLayer) mapInstanceRef.current.removeLayer(layer);
    });
    L.tileLayer(
      darkMode
        ? "https://{s}.basemaps.cartocdn.com/rastertiles/dark_all/{z}/{x}/{y}{r}.png"
        : "https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png",
      { attribution: '&copy; <a href="https://carto.com/">CARTO</a> &copy; <a href="https://www.openstreetmap.org/copyright">OSM</a>', subdomains: "abcd", maxZoom: 19 }
    ).addTo(mapInstanceRef.current);
  }, [darkMode]);

  // Update markers when items change
  useEffect(() => {
    if (!mapInstanceRef.current) return;

    // Clear old markers
    markersRef.current.forEach(m => m.remove());
    markersRef.current = [];

    items.forEach(item => {
      const icon = L.divIcon({
        className: "network-map-pin",
        html: `<div style="display:flex;flex-direction:column;align-items:center">
          <img src="${item.photo || item.logo}" style="width:40px;height:40px;border-radius:50%;object-fit:cover;border:3px solid #604DFF;box-shadow:0 2px 10px rgba(0,0,0,.2)" />
          <div style="width:2px;height:8px;background:#604DFF"></div>
          <div style="width:6px;height:6px;border-radius:50%;background:#604DFF"></div>
        </div>`,
        iconSize: [46, 62],
        iconAnchor: [23, 62],
        popupAnchor: [0, -65],
      });

      const marker = L.marker([item.lat, item.lng], { icon }).addTo(mapInstanceRef.current);
      const popupContent = networkTab === "people"
        ? `<div style="text-align:center"><img src="${item.photo}" style="width:48px;height:48px;border-radius:50%;object-fit:cover;margin-bottom:6px" /><div style="font-weight:600;font-size:13px">${item.name}</div><div style="font-size:11px;color:#888;margin-top:2px">${item.role}${item.company ? ' · ' + item.company : ''}</div><div style="font-size:10px;color:#aaa;margin-top:4px">${EIS.mapPin} ${item.location}</div><div style="margin-top:6px;display:flex;gap:4px;justify-content:center;flex-wrap:wrap">${(item.styles || []).map(s => '<span style="font-size:9px;padding:2px 6px;border-radius:10px;background:rgba(96,77,255,.1);color:#604DFF">' + s + '</span>').join('')}</div></div>`
        : `<div style="text-align:center"><img src="${item.logo}" style="width:48px;height:48px;border-radius:50%;object-fit:cover;margin-bottom:6px" /><div style="font-weight:600;font-size:13px">${item.name}</div><div style="font-size:11px;color:#888;margin-top:2px">${item.type}</div><div style="font-size:10px;color:#aaa;margin-top:4px">${EIS.mapPin} ${item.location}</div>${item.openPositions ? '<div style="font-size:10px;color:#604DFF;margin-top:4px;font-weight:600">' + item.openPositions + ' open positions</div>' : ''}</div>`;
      marker.bindPopup(popupContent, { maxWidth: 220, closeButton: true });
      markersRef.current.push(marker);
    });

    // Fit bounds if items exist
    if (items.length > 0) {
      const bounds = L.latLngBounds(items.map(i => [i.lat, i.lng]));
      mapInstanceRef.current.fitBounds(bounds, { padding: [50, 50], maxZoom: 5 });
    }
  }, [items, networkTab]);

  return (
    <div className="network-map" style={{ position: "relative" }}>
      <div ref={mapRef} style={{ width: "100%", height: "100%" }} />
      <div style={{ position: "absolute", inset: 0, background: "rgba(96,77,255,.03)", pointerEvents: "none", zIndex: 400 }} />
    </div>
  );
}

/* ━━━ SHARED FILTER PANEL (right-anchored overlay, used on Network etc.) ━━━ */
function FilterPanel({ open, onClose, title, subtitle, filters, onChange, onClear, styleOptions = [], locationOptions = [], roleOptions = null }) {
  if (!open) return null;
  const f = filters || {};
  return createPortal(
    <>
      <div className="filter-side-backdrop" onClick={onClose} />
      <aside className="filter-side-panel" onClick={e => e.stopPropagation()}>
        <div className="fsp-header">
          <div>
            <h2>{title || "Filters"}</h2>
            {subtitle && <div className="fsp-sub">{subtitle}</div>}
          </div>
          <button className="fsp-close" onClick={onClose} aria-label="Close filters"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg></button>
        </div>
        <div className="fsp-body">
          <div className="afm-section">
            <h3>Role &amp; Style</h3>
            <div className="afm-grid">
              <div className="field">
                <label>{roleOptions ? "Role" : "Type"}</label>
                <select value={f.artistType || "all"} onChange={e => onChange("artistType", e.target.value)}>
                  <option value="all">{roleOptions ? "All Roles" : "Any type"}</option>
                  {(roleOptions || ["Dancer","Choreographer","Model","Actor","Singer","Teacher"]).map(r => <option key={r} value={r}>{r}</option>)}
                </select>
              </div>
              <div className="field">
                <label>Style / Genre</label>
                <select value={f.style || "all"} onChange={e => onChange("style", e.target.value)}>
                  <option value="all">Any style</option>
                  {styleOptions.map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <div className="field">
                <label>Skills</label>
                <input placeholder="e.g. Pointe, Improvisation, Partnering" value={f.skills || ""} onChange={e => onChange("skills", e.target.value)}/>
              </div>
            </div>
          </div>
          <div className="afm-section">
            <h3>Location</h3>
            <div className="afm-grid">
              <div className="field">
                <label>City or Country</label>
                {locationOptions.length ? (
                  <select value={f.location || "all"} onChange={e => onChange("location", e.target.value)}>
                    <option value="all">Any location</option>
                    {locationOptions.map(l => <option key={l} value={l}>{l}</option>)}
                  </select>
                ) : (
                  <input placeholder="e.g. Berlin, Germany" value={f.location || ""} onChange={e => onChange("location", e.target.value)}/>
                )}
              </div>
            </div>
          </div>
          <div className="afm-section">
            <h3>Personal</h3>
            <div className="afm-grid">
              <div className="field">
                <label>Gender</label>
                <select value={f.gender || "all"} onChange={e => onChange("gender", e.target.value)}>
                  <option value="all">Any</option>
                  <option value="Female">Female</option>
                  <option value="Male">Male</option>
                  <option value="Non-binary">Non-binary</option>
                </select>
              </div>
              <div className="field">
                <label>Ethnicity</label>
                <input placeholder="e.g. Asian, Black, Latinx" value={f.ethnicity || ""} onChange={e => onChange("ethnicity", e.target.value)}/>
              </div>
              <div className="field">
                <label>Nationality</label>
                <input placeholder="e.g. British" value={f.nationality || ""} onChange={e => onChange("nationality", e.target.value)}/>
              </div>
              <div className="field">
                <label>Age</label>
                <div className="afm-range">
                  <input type="number" placeholder="Min" value={f.ageMin || ""} onChange={e => onChange("ageMin", e.target.value)}/>
                  <span>—</span>
                  <input type="number" placeholder="Max" value={f.ageMax || ""} onChange={e => onChange("ageMax", e.target.value)}/>
                </div>
              </div>
              <div className="field">
                <label>Height (cm)</label>
                <div className="afm-range">
                  <input type="number" placeholder="Min" value={f.heightMin || ""} onChange={e => onChange("heightMin", e.target.value)}/>
                  <span>—</span>
                  <input type="number" placeholder="Max" value={f.heightMax || ""} onChange={e => onChange("heightMax", e.target.value)}/>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div className="fsp-actions">
          <button className="btn-clear" onClick={onClear}>Clear All</button>
          <button className="btn-apply" onClick={onClose}>Done</button>
        </div>
      </aside>
    </>,
    document.body
  );
}

